			/**
			 * 콤보박스 목록 데이터 조회
			 * 
			 * @param {String} psDsName         데이터셋 이름
			 * @param {String} psTypeVal        콤보박스유형값
			 * @param poReqData                 요청 데이터
			 * @param poCallbackFunc            조회후 처리할 콜백
			 */
			function doComboDataList(psDsName, psTypeVal, poReqData, poCallbackFunc) {
			    // 요청 데이터맵 초기화
			    util.DataMap.clear(app, "dmCmbSrch");
			    
			    // 대상 데이터셋 설정
			    util.DataMap.setValue(app, "dmCmbSrch", "DS_NAME", psDsName);
			    util.DataMap.setValue(app, "dmCmbSrch", "CMB_TYPE_VAL", psTypeVal);
			    
			    // 요청 데이터 설정
			    if (poReqData != undefined) {
			        for (var key in poReqData) {
			            util.DataMap.setValue(app, "dmCmbSrch", key, poReqData[key]);
			        }
			    }
			    
			    // 콤보박스 데이터 조회
			    util.Submit.send(app, "subComboLoad", function(pbSuccess) {
			        if (pbSuccess) {
			            // 콜백이 존재시 콜백함수 호출       
			            if (typeof poCallbackFunc == "function") {
			                poCallbackFunc(pbSuccess);
			            }
			            
			            app.lookup("grpData").redraw();
			        }
			    });
			}

