			/**
			 * 변경사항을 체크합니다.
			 * 
			 * @param {any} voChangeData  변경된 데이터 객체 (Object)
			 * @return {Boolean} 변경유무
			 */
			function _isModified(voChangeData) {

			    var dmSelectAplyInst = app.lookup("dmSelectAplyInst");
			    
			    var voBeforeData = {
			        "groupAuthrtSeCd" : dmSelectAplyInst.getValue("GROUP_AUTHRT_SE_CD"),
			        "authrtSeCd" : dmSelectAplyInst.getValue("AUTHRT_SE_CD"),
			    };
			    
			    var isModified = false;
			    var vnChangeCnt = 0;

			    var vaBeforeKeys = Object.keys(voBeforeData);
			    var vaChangeKeys = Object.keys(voChangeData);
			    
			    vaBeforeKeys.forEach(function(key) {
			        if (voBeforeData[key] != voChangeData[key]) {
			            vnChangeCnt++;
			        }
			    });
			    isModified = vnChangeCnt > 0;
			    
			    return isModified;
			}

			/**
			 * 단위업무 메뉴권한 값 체크
			 */
			function _isEmptyByUntTaskwkMenuAuthrt() {
			    var isEmpty = true;
			    
			    var untTaskwkMenuAuthrtCn = util.DataSet.getValue(app, "dsUserAuthrtAply", 0, "UNT_TASKWK_MENU_AUTHRT_CN");
			    if (!ValueUtil.isNull(untTaskwkMenuAuthrtCn)) {
			        var untTaskwkMenuAuthrtData = JSON.parse(untTaskwkMenuAuthrtCn);
			        if (untTaskwkMenuAuthrtData) {
			            /** @type Array */
			            var voItems = untTaskwkMenuAuthrtData.items;
			            if (voItems && voItems.length > 0) {
			                isEmpty = false;
			            }
			        }
			    }
			    
			    return isEmpty;
			    
			}

