			/*
			 * 콤보 박스에서 selection-change 이벤트 발생 시 호출.
			 * ComboBox Item을 선택하여 선택된 값이 저장된 후에 발생하는 이벤트.
			 */
			function onCmbUntTaskwkSelectionChange(e){
			    console.log("=== onCmbUntTaskwkSelectionChange");
			    var cmbUntTaskwk = e.control;
			    
			    // 권한유형 필터링
			    setFilterByDtlAuthrt("cmbDtlAuthrt", cmbUntTaskwk.value);
			    
			    // 선택된 신청 기관의 단위업무구분코드와 다르면 권한유형 콤보박스 selection 초기화
			    var currUntTaskwkSeCd = util.DataMap.getValue(app, "dmSelectAplyInst", "UNT_TASKWK_SE_CD");
			    if (currUntTaskwkSeCd != cmbUntTaskwk.value) {
			        app.lookup("cmbDtlAuthrt").selectItem(0);
			    }
			    
			    // 지역 (시/도) 콤보박스 데이터 조회
			    doComboDataList("dsCmbSido", "RGN_SIDO", { 
			        "UNT_TASKWK_SE_CD" : cmbUntTaskwk.value
			    }, function(pbSuccess) {
			        if (pbSuccess) {
			            // 지역 (시/도) 콤보박스 초기화
			            var cmbRgnSido = app.lookup("cmbRgnSido");
			            cmbRgnSido.clearSelection(false);
			            cmbRgnSido.selectItem(0);
			        }
			    });
			    
			    // 직위구분코드 데이터 조회
			    var dsCommParam = app.lookup("dsCommParam");
			    dsCommParam.clear();
			    
			    dsCommParam.addRowData({
			        "CMMNS_ID": "JBPS_SE_CD",
			        "UNIT_CODE": cmbUntTaskwk.value,
			        "DS_NAME": "dsJbgdSeCd"
			    });
			    
			    /* 단위업무별 공통코드 목록 조회 서브미션 호출 */
			    util.Submit.send(app, "subCommCodeByUnitSystem", function(pbSuccess) {
			        if (pbSuccess) {
			            // 직위 선택 콤보박스 초기화
			            app.lookup("cmbJbgdSeCd").selectItem(0);
			            
			            // 직위 선택 콤보박스 - 'selection-change' 실행
			            util.Control.dispatchEvent(app, "cmbJbgdSeCd", "selection-change");
			        }
			    });
			    
			    // 선택된 신청유형 조회
			    var vsAplyTypeVal = util.Control.getValue(app, "cmbAplyType");
			    
			    // 기관변경신청, 기관추가신청 일때 
			    if (vsAplyTypeVal == "06" || vsAplyTypeVal == "07") {
			        // 권한 구분 비활성화 처리 및 selection 초기화
			        util.Control.setEnable(app, false, ["cmbGroupAuthrt", "cmbDtlAuthrt"]);
			        
			        app.lookup("cmbGroupAuthrt").selectItem(0);
			        app.lookup("cmbDtlAuthrt").selectItem(0);    
			    }
			}

