			function onCmbRgnSggSelectionChange(e){
			    var cmbRgnSgg = e.control;
			    var cmbRgnInst = app.lookup("cmbRgnInst");
			    
			    // 지역 (시/군/구) 존재 여부 확인
			    var bSggExist = check_rgnSggExist("dsCmbSgg");
			    var ctpvSrchYn = "N";
			    var bFindSidoInsts = false;
			    if (bSggExist) {
			        bFindSidoInsts = check_srchSidoInst("dsCmbSido");
			    }
			    console.log("bFindSidoInsts: ",  bFindSidoInsts);
			    
			    var untTaskwkSeCd = util.Control.getValue(app, "cmbUntTaskwk");
			    var ctpvCd = util.Control.getValue(app, "cmbRgnSido");
			    var sggCd = cmbRgnSgg.value;
			    
			    // 지역(시/도) 전체 선택시 처리
			    if (ValueUtil.isNull(ctpvCd)) {
			        console.log("=== onCmbRgnSggSelectionChange: 지역(시/도) 전체 선택");
			        
			        // 기관 선택 콤보박스 비활성화
			        util.Control.setEnable(app, false, "cmbRgnInst");
			        
			        // 기관선택 ComboBox 초기화
			        cmbRgnInst.clearSelection(false);
			        cmbRgnInst.selectItem(0);
			        return false;
			    }
			    
			    ctpvSrchYn = (sggCd == "" && bFindSidoInsts) ? "Y" : "N";
			    console.log("ctpvSrchYn: ", ctpvSrchYn);
			    
			    doComboDataList("dsCmbInst", "INST", { 
			        "UNT_TASKWK_SE_CD" : untTaskwkSeCd,
			        "CTPV_CD" : ctpvCd,
			        "SGG_CD" : ValueUtil.isNull(sggCd) ? null : cmbRgnSgg.value,
			        "CTPV_SRCH_YN" : ctpvSrchYn
			    }, function(pbSuccess) {
			        if (pbSuccess) {
			            // 기관 선택 콤보박스 활성화 여부 설정
			            util.Control.setEnable(app, true, "cmbRgnInst");
			            
			            // 기관선택 ComboBox 초기화
			            cmbRgnInst.clearSelection(false);
			            cmbRgnInst.selectItem(0);
			        }
			    });
			}

